<script setup lang="ts">
import { ref, onMounted } from 'vue'

const theme = ref<'light' | 'dark'>('light')

onMounted(() => {
  const saved = localStorage.getItem('learn-java-theme') as 'light' | 'dark' | null
  if (saved) {
    theme.value = saved
    document.documentElement.setAttribute('data-theme', saved)
  }
})

const toggleTheme = () => {
  theme.value = theme.value === 'light' ? 'dark' : 'light'
  document.documentElement.setAttribute('data-theme', theme.value)
  localStorage.setItem('learn-java-theme', theme.value)
}
</script>

<template>
  <header class="site-header">
    <div class="container header-inner">
      <RouterLink to="/" class="brand">
        <span class="logo">J</span>
        <span class="brand-name">Learn Java</span>
        <span class="brand-tag">从零到中级</span>
      </RouterLink>

      <nav class="nav">
        <RouterLink to="/" class="nav-link">首页</RouterLink>
        <RouterLink to="/roadmap" class="nav-link">学习路线</RouterLink>
        <RouterLink to="/docs/java/01-intro" class="nav-link">Java</RouterLink>
        <RouterLink to="/docs/mysql/01-install" class="nav-link">MySQL</RouterLink>
        <RouterLink to="/docs/project/01-overview" class="nav-link">商城项目</RouterLink>
      </nav>

      <el-button text @click="toggleTheme" class="theme-btn">
        <el-icon><component :is="theme === 'light' ? 'Moon' : 'Sunny'" /></el-icon>
        <span style="margin-left: 4px">{{ theme === 'light' ? '深色' : '浅色' }}</span>
      </el-button>
    </div>
  </header>
</template>

